function MaidCoffeeCatDrawEntryDialog:PlayCamera(viewPort, duration)
    local Duration = duration or 0.7
    print(viewPort)
    ---切换镜头的按钮的逻辑
    local sequence = DOTween.Sequence()
    --if viewPort == STATE.START then
    --    ---切到第二个镜头参数
    --    local transform = self.mCamera.transform
    --    local t = ViewPorts[viewPort]
    --    sequence:Append(transform:DOMove(t.pos, Duration))
    --    sequence:Join(transform:DORotateQuaternion(t.rot, Duration))
    --    sequence:PlayForward()
    --elseif viewPort == STATE.BEGIN then
    --elseif viewPort == STATE.END then
    self.mCamera.fieldOfView = 75.439
    self.mCamera.focalLength = 32.969
    if viewPort == STATE.ORIGIN then
        KTool.SetActive(self.vmCamera.gameObject, true)
        ---@type Cinemachine.CinemachineFreeLook
        local freeLook = self.vmCamera.gameObject:GetComponent(typeof(CS.Cinemachine.CinemachineFreeLook))
        freeLook:InternalUpdateCameraState(Vector3.up, 0)
        freeLook:ForceCameraPosition(ViewPorts[STATE.START].pos, ViewPorts[STATE.START].rot)
        KTool.SetActive(self.vmCamera.gameObject, false)
        local transform = self.mCamera.transform
        sequence:Append(transform:DOMove(freeLook.State.RawPosition, Duration))
        sequence:Join(transform:DORotateQuaternion(freeLook.State.RawOrientation, Duration))
        sequence:OnComplete(function()
            KTool.SetActive(self.vmCamera.gameObject, true)
            UIModule.BackDialog()
        end)
        sequence:PlayForward()
    else
        ---切到第二个镜头参数
        local transform = self.mCamera.transform
        local t = ViewPorts[viewPort]
        sequence:Append(transform:DOMove(t.pos, Duration))
        sequence:Join(transform:DORotateQuaternion(t.rot, Duration))
        sequence:PlayForward()
    end
end

