---OnDrawCatsAction
---@param poolId number
---@param type number
function MaidCoffeeCatDrawEntryDialog:OnDrawCatsAction(poolId, type, goodsId, num)
    GameUtils.Request(Interfaces.MaidCoffeeCatCall, { poolId = poolId, type = type, consumeId = goodsId }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            GoodsUtils.DrawRewards({ { goodsId = goodsId, num = -num } })
            self:FreshGoodsConsume()
            local data = checkTable(response.data)
            if table.count(data.cats) > 0 then
                KTool.SetActive(self.controller.gameObject, false)
                CfUtils.SetTopCommonActive(false, false)
                ---抽到猫的展示
                ----先加入数据
                ---@type CatEggComponent
                local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
                local t = {}
                local rewards = {}
                local goods = {} ---goods
                for i, v in pairs(data.cats) do
                    ---@type CatEggDojo
                    local dojo = CatEggDojo.New()
                    dojo:FillData(v)
                    if isNull(v.convertGoods) then
                        ---表示是猫
                        local isHave = eggComponent:HasCatById(v.id)
                        ---@type MaidCoffeeCatRollConfigVo
                        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4000, 'MaidCoffeeCatRollConfigVo', dojo.catId)
                        eggComponent:DrawCatDrawReward(dojo)
                        if checkNumber(vo.quality) == MaidCoffeeConstants.CatBallQuality.Theme then
                            local dojoClone = clone(dojo)
                            dojoClone.isNew = (not isHave)
                            table.insert(t, dojoClone)
                        else
                            table.insert(rewards, dojo)
                        end
                    else
                        table.insert(rewards, dojo)
                        table.insert(goods, {
                            goodsId = v.convertGoods.goodsId,
                            num = v.convertGoods.num,
                        })
                    end
                end
                ----表现的逻辑
                print('----->>>', #t, #goods)
                if #goods > 0 then
                    GoodsUtils.DrawRewards(goods, true)
                end
                UIRaycastBlocker:AddCondition("DrawingCatSequence")
                xTry(function()
                    cs_coroutine.start(function()
                        self:PlayCamera(STATE.BEGIN)
                        if self.machineEnv then
                            self.machineEnv:PlayAnimation()
                        end
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
                        ---再向下移动相机的
                        self:PlayCamera(STATE.END)
                        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.4))
                        ----建立小球节点
                        if self.machineEnv then
                            self.machineEnv:CreateBall(data.cats)
                        end
                        coroutine.yield(CS.UnityEngine.WaitForSeconds(1.5))
                        if #t > 0 then
                            ---有需要展示的猫
                            KTool.SetActive(self.controller.gameObject, false)
                            for i, v in pairs(t) do
                                table.insert(rewards, v)
                            end
                            UIModule.OpenDialog(UIArgs(Constants.UITypeIds.MaidCoffeeCatDrawPreviewDialog, { cats = t, cb = function()
                                ---回调后再进行奖励弹出
                                KTool.SetActive(self.controller.gameObject, true)
                                -----再向下移动相机的
                                --self:PlayCamera(STATE.END)
                                self:PlayCamera(STATE.END, 0)
                                self.isShowCapture = true
                                UIModule.OpenDialog(
                                        {
                                            id = Constants.UITypeIds.UICommonRewardPop,
                                            parameters = { rewards = rewards, cb = function()
                                                if self then
                                                    self:PlayCamera(STATE.START, 0)
                                                    self.isShowCapture = false
                                                end
                                            end }
                                        }
                                )
                            end }))
                        else
                            ---直接弹出奖励预览的逻辑
                            if #rewards > 0 then
                                self.isShowCapture = true
                                UIModule.OpenDialog(
                                        {
                                            id = Constants.UITypeIds.UICommonRewardPop,
                                            parameters = { rewards = rewards , cb = function()
                                                if self then
                                                    self:PlayCamera(STATE.START, 0)
                                                    self.isShowCapture = false
                                                end
                                            end}
                                        }
                                )
                                KTool.SetActive(self.controller.gameObject, true)
                            end
                        end
                        -----还原到相机1
                        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.3))
                        CfUtils.SetTopCommonActive(true, true)
                        if self.machineEnv then
                            self.machineEnv:StopAnimation()
                        end
                        
                        UIRaycastBlocker:RemoveCondition("DrawingCatSequence")
                    end)
                end, function()
                    if self.machineEnv then
                        self.machineEnv:StopAnimation()
                    end
                    UIRaycastBlocker:RemoveCondition("DrawingCatSequence")
                end)
            end
        end
    end)
end

function MaidCoffeeCatDrawEntryDialog:HandleBackAction()
    Events.Broadcast("MaidCoffeeChangeRoleStatus",true)
    self:PlayCamera(STATE.ORIGIN)
    KTool.SetActive(self.controller.gameObject, false)
end

function MaidCoffeeCatDrawEntryDialog:OnFocus(focus)
    if focus then
        CfUtils.RefreshTopGoods({ 4199005, Constants.Currency.GoldId})
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        eggComponent:SetCaptureNode(true)
    else
        if not self.isShowCapture then
            ---@type CatEggComponent
            local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
            eggComponent:SetCaptureNode(false)
        end
        self.isShowCapture = false
    end


end
function MaidCoffeeCatDrawEntryDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        while not self.isFinish do
            coroutine.yield()
        end
        ---更新列表
        --- poolId, poolType, poolName, poolDesc, remainSeconds
        self:FreshGoodsConsume()
        
    end))
    return coWait
end

function MaidCoffeeCatDrawEntryDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        GameUtils.Request(Interfaces.MaidCoffeeCatHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local data = checkTable(response.data)
                self.catPools = data.catPools
                ---@type CatEggComponent
                local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
                eggComponent:SetExtendTimes(checkNumber(data.catBackpackUnlockTimes))
                eggComponent:SetConvertBackpack(data.convertBackpack)
                if data.autoConvert then
                    local t = string.split(data.autoConvert, ',')
                    eggComponent:SetAutoConvertStetting(t)
                end
                self.isFinish = true
            end
        end)
    end))
    return coWait
end

function MaidCoffeeCatDrawEntryDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function MaidCoffeeCatDrawEntryDialog:FreshGoodsConsume()
    local pool = table.takeFirst(self.catPools)
    if pool then
        local oneConsume = pool.oneConsume
        local imageTans = self.BtnConsumePopOne.transform:Find("Image")
        local textTans = self.BtnConsumePopOne.transform:Find("Text2")
        local num = checkNumber(oneConsume.num)
        local goodsId = oneConsume.goodsId
        local havNo = GoodsUtils.GetThingNo(goodsId)
        if havNo < num then
            goodsId = pool.oneConsumeOther.goodsId
            num = checkNumber(pool.oneConsumeOther.num)
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local status = GoodsUtils.GetThingNo(goodsId) < num and 3 or 1
            CfUtils.FillImage(imageTans, goodsVo.photoPath)
            CfUtils.FillText(textTans, num)
            CfUtils.SetUISwitchText(textTans, status)
        else
            ---第一种道具充足
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(oneConsume.goodsId)
            CfUtils.FillImage(imageTans, goodsVo.photoPath)
            CfUtils.FillText(textTans, oneConsume.num)
            CfUtils.SetUISwitchText(textTans, 1)
        end

        KTool.SetActive(self.BtnOneNode.gameObject, true)
        KTool.SetActive(self.BtnTenNode.gameObject, true)

        local tenConsume = pool.tenConsume
        local goodsId = tenConsume.goodsId
        local num = checkNumber(tenConsume.num)
        local havNo = GoodsUtils.GetThingNo(goodsId)
        if havNo < num then
            goodsId = pool.tenConsumeOther.goodsId
            num = checkNumber(pool.tenConsumeOther.num)
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local status = GoodsUtils.GetThingNo(goodsId) < num and 3 or 1
            local imageTans = self.BtnConsumePopTen.transform:Find("Image")
            local textTans = self.BtnConsumePopTen.transform:Find("Text2")
            CfUtils.FillImage(imageTans, goodsVo.photoPath)
            CfUtils.FillText(textTans, tostring(num))
            CfUtils.SetUISwitchText(textTans, status)
        else
            ---第一种道具充足
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(tenConsume.goodsId)
            local imageTans = self.BtnConsumePopTen.transform:Find("Image")
            local textTans = self.BtnConsumePopTen.transform:Find("Text2")
            CfUtils.FillImage(imageTans, goodsVo.photoPath)
            CfUtils.FillText(textTans, tostring(tenConsume.num))
            CfUtils.SetUISwitchText(textTans, 1)
        end
    end
end

return MaidCoffeeCatDrawEntryDialog